export type ParsedAttackInstruction<
  TProgram extends string = typeof PINATA_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    attacker: TAccountMetas[0];
    arbiter: TAccountMetas[1];
    session: TAccountMetas[2];
    hpVault: TAccountMetas[3];
    hpMint: TAccountMetas[4];
    solPile: TAccountMetas[5];
    instructionsSysvar: TAccountMetas[6];
    token2022Program: TAccountMetas[7];
    systemProgram: TAccountMetas[8];
  };
  data: AttackInstructionData;
};

export function parseAttackInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedAttackInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 9,
      }
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      attacker: getNextAccount(),
      arbiter: getNextAccount(),
      session: getNextAccount(),
      hpVault: getNextAccount(),
      hpMint: getNextAccount(),
      solPile: getNextAccount(),
      instructionsSysvar: getNextAccount(),
      token2022Program: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getAttackInstructionDataDecoder().decode(instruction.data),
  };
}
